INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アヤネ", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 401, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 2, 0, 24001, 2, 24, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アヤネ", "2020/07/31 12:00:00", 2.21, "2030/12/17 14:59:59", 402, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 1, 0, 24002, 2, 24, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アヤネ", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 403, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 2, 0, 24003, 2, 24, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アサヒ", "2020/07/31 12:00:00", 1.99, "2030/12/17 14:59:59", 701, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 2, 0, 24004, 1, 24, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アサヒ", "2020/07/31 12:00:00", 2.21, "2030/12/17 14:59:59", 702, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 1, 0, 24005, 2, 24, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アサヒ", "2020/07/31 12:00:00", 3.33, "2030/12/17 14:59:59", 703, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 2, 0, 24006, 1, 24, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "部員３", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 801, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 2, 0, 24007, 2, 24, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "部員３", "2020/07/31 12:00:00", 2.68, "2030/12/17 14:59:59", 802, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 1, 0, 24008, 2, 24, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "部員３", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 803, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 2, 0, 24009, 2, 24, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 501, "やった！", 1, 0, 24010, 1, 24, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 502, "勝ったよ！", 1, 0, 24011, 1, 24, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 503, "いい調子！", 1, 0, 24012, 1, 24, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 5.33, "2030/12/17 14:59:59", 111, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 6, 0, 24013, 2, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 6.85, "2030/12/17 14:59:59", 112, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 1, 0, 24014, 2, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 3, "2030/12/17 14:59:59", 113, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 1, 0, 24015, 2, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ダイチ", "2020/07/31 12:00:00", 6.11, "2030/12/17 14:59:59", 611, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 1, 0, 24016, 2, 24, 192401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ダイチ", "2020/07/31 12:00:00", 6.75, "2030/12/17 14:59:59", 612, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 1, 0, 24017, 2, 24, 192401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ダイチ", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 613, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 2, 0, 24018, 2, 24, 192401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ハツネ", "2020/07/31 12:00:00", 4.52, "2030/12/17 14:59:59", 211, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 2, 0, 24019, 1, 24, 113401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ハツネ", "2020/07/31 12:00:00", 3.89, "2030/12/17 14:59:59", 212, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 2, 0, 24020, 1, 24, 113401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ハツネ", "2020/07/31 12:00:00", 13.49, "2030/12/17 14:59:59", 213, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 1, 0, 24021, 2, 24, 113401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "カヤ", "2020/07/31 12:00:00", 3.17, "2030/12/17 14:59:59", 311, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 1, 0, 24022, 2, 24, 106501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "カヤ", "2020/07/31 12:00:00", 4.42, "2030/12/17 14:59:59", 312, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 1, 0, 24023, 2, 24, 106501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "カヤ", "2020/07/31 12:00:00", 2.89, "2030/12/17 14:59:59", 313, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 6, 0, 24024, 1, 24, 106501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アヤネ", "2020/07/31 12:00:00", 3.71, "2030/12/17 14:59:59", 421, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 4, 0, 24025, 3, 24, 102301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "アサヒ", "2020/07/31 12:00:00", 5.1, "2030/12/17 14:59:59", 721, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 2, 0, 24026, 1, 24, 192201);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "部員３", "2020/07/31 12:00:00", 4.34, "2030/12/17 14:59:59", 821, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 1, 0, 24027, 3, 24, 192301);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 521, "いい勝負だったよ\nまたやろうね", 1, 0, 24028, 1, 24, 192501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 5.62, "2030/12/17 14:59:59", 101, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 1, -360, 24029, 2, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 9.58, "2030/12/17 14:59:59", 102, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 1, -360, 24030, 2, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 0, "2030/12/17 14:59:59", 103, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 2, -360, 24031, 2, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 9.13, "2030/12/17 14:59:59", 104, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 2, -360, 24032, 1, 24, 113501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (10046, 0, "ミサト", "2020/07/31 12:00:00", 8.27, "2030/12/17 14:59:59", 105, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 1, -360, 24033, 2, 24, 113501);
